<template><section class="reference-home"><header class="reference-page-heading"><div><h1>工作台</h1><p>平台课程、资源和实训环境总览</p></div><div class="reference-heading-actions"><el-button icon="el-icon-refresh" :loading="loading" @click="refreshAll">刷新数据</el-button><el-button type="primary" icon="el-icon-video-play" @click="openClassDialog">一键上课</el-button></div></header><div class="reference-layout"><main class="reference-main-column"><section class="storage-hero"><div class="storage-ring"><el-progress type="circle" :percentage="resourcePercent" :width="112" :stroke-width="9" color="#ffffff" :show-text="false" /><div><strong>{{ resourcePercent }}%</strong><span>资源使用</span></div></div><div class="storage-copy"><small>平台资源空间</small><strong>{{ resourceCount }} 项资源</strong><span>{{ courseCount }} 门课程 · {{ environmentCount }} 个实训环境</span></div></section><section class="category-grid"><button v-for="item in categories" :key="item.key" type="button" class="category-card" @click="$router.push(item.route)"><span class="category-icon" :class="item.tone"><i :class="item.icon" /></span><strong>{{ item.value }}</strong><small>{{ item.label }}</small><em>{{ item.note }}</em></button></section></main><aside class="reference-side-column"><section class="reference-panel contact-panel"><header><h2>平台联系人</h2><i class="el-icon-info" /></header><div class="contact-row"><span class="contact-avatar admin-avatar">{{ adminInitial }}</span><div><strong>{{ adminName }}</strong><small>当前管理账号</small></div><el-tag size="mini" type="success">在线</el-tag></div><div class="contact-row"><span class="contact-avatar server-avatar"><i class="el-icon-cpu" /></span><div><strong>处理服务器</strong><small>{{ onlineAgents }} 台在线 / {{ totalAgents }} 台</small></div><el-tag size="mini" :type="onlineAgents ? 'success' : 'info'">{{ onlineAgents ? '正常' : '待接入' }}</el-tag></div><div class="contact-row"><span class="contact-avatar course-avatar"><i class="el-icon-reading" /></span><div><strong>课程与资源</strong><small>{{ publishedCourses }} 门课程已发布</small></div><el-tag size="mini" type="info">{{ resourceCount }} 项</el-tag></div></section><section class="reference-panel quick-panel"><header><h2>快捷入口</h2></header><button type="button" @click="$router.push('/management/courses')"><i class="el-icon-reading" /><span>课程管理</span><b class="el-icon-arrow-right" /></button><button type="button" @click="$router.push('/management/resources')"><i class="el-icon-folder-opened" /><span>资源管理</span><b class="el-icon-arrow-right" /></button><button type="button" @click="$router.push('/management/training')"><i class="el-icon-monitor" /><span>实训环境</span><b class="el-icon-arrow-right" /></button><button type="button" @click="$router.push('/management/users')"><i class="el-icon-user" /><span>平台用户</span><b class="el-icon-arrow-right" /></button></section></aside></div><el-dialog title="一键上课" :visible.sync="classDialog" width="460px"><el-form label-width="90px"><el-form-item label="课程名称"><el-select v-model="classForm.courseId" filterable placeholder="选择需要启动的课程" style="width:100%"><el-option v-for="item in courses" :key="item.course.courseId" :label="item.course.name" :value="item.course.courseId" /></el-select></el-form-item><el-form-item label="代码工具"><el-select v-model="classForm.tool" style="width:100%"><el-option label="VS Code（9091-9094）" value="vscode" /><el-option label="Jupyter Notebook（8881-8884）" value="jupyter" /></el-select></el-form-item></el-form><span slot="footer"><el-button @click="classDialog=false">取消</el-button><el-button type="primary" :loading="classStarting" @click="startSelectedClass">确认上课</el-button></span></el-dialog></section></template>
<script>
import { getDashboardOverview } from '@/api/DashboardOverview'
import { listAdminCourses } from '@/api/Courses'
import { listAdminTrainingEnvironments, startAdminTrainingEnvironment } from '@/api/TrainingEnvironments'
export default { data:()=>({loading:false,snapshot:null,courses:[],classDialog:false,classStarting:false,classForm:{courseId:'',tool:'vscode'},refreshTimer:null}), computed:{adminName(){return this.$store.state.Match.userInfo&&this.$store.state.Match.userInfo.userName||'管理员'},adminInitial(){return this.adminName.slice(0,1).toUpperCase()},agents(){return(this.snapshot&&this.snapshot.agents)||{}},environments(){return(this.snapshot&&this.snapshot.environments)||{}},totalAgents(){return Number(this.agents.enabled||0)},onlineAgents(){return Number(this.agents.online||0)},courseCount(){return this.courses.length},publishedCourses(){return this.courses.filter(item=>item.course.enabled).length},resourceCount(){return this.courses.reduce((sum,item)=>sum+(item.resources||[]).length,0)},environmentCount(){return Number(this.environments.total||this.environments.running||0)},resourcePercent(){return Math.min(100,Math.round(this.resourceCount?Math.max(8,this.resourceCount/Math.max(this.courseCount,1)*10):0))},categories(){const resources=this.courses.reduce((all,item)=>all.concat(item.resources||[]),[]);const count=t=>resources.filter(r=>r.resourceType===t).length;return[{key:'ebook',label:'电子书',value:count('EBOOK'),note:'在线预览',icon:'el-icon-document',tone:'coral',route:'/management/resources'},{key:'video',label:'视频课件',value:count('VIDEO'),note:'在线播放',icon:'el-icon-video-play',tone:'blue',route:'/management/resources'},{key:'ppt',label:'PPT 课件',value:count('PPT'),note:'在线查看',icon:'el-icon-data-board',tone:'green',route:'/management/resources'},{key:'archive',label:'课程数据',value:count('ARCHIVE'),note:'发送到实训',icon:'el-icon-folder',tone:'purple',route:'/management/resources'}]}},mounted(){this.refreshAll();this.refreshTimer=setInterval(this.refreshAll,15000)},beforeDestroy(){clearInterval(this.refreshTimer)},methods:{async refreshAll(){this.loading=true;try{const [overview,courses]=await Promise.all([getDashboardOverview(),listAdminCourses()]);this.snapshot=overview.data||{};this.courses=courses.data||[]}finally{this.loading=false}},openClassDialog(){this.classDialog=true},async startSelectedClass(){if(!this.classForm.courseId){this.$message.warning('请选择需要启动的课程');return}this.classStarting=true;try{const result=await listAdminTrainingEnvironments();const environment=(result.data||[]).find(item=>String(item.courseId)===String(this.classForm.courseId)&&item.userId!=null);if(!environment){this.$message.warning('该课程尚未绑定用户或创建实训环境');return}if(environment.actualState==='RUNNING'){this.$message.success('该课程环境已经在运行');this.classDialog=false;return}await startAdminTrainingEnvironment(environment.environmentId);this.classDialog=false;this.$message.success(`${this.classForm.tool==='vscode'?'VS Code':'Jupyter Notebook'} 启动任务已提交`)}finally{this.classStarting=false}}}}
</script>
<style scoped>.reference-home{width:100%;color:var(--ui-text)}.reference-page-heading{display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:18px}.reference-page-heading h1{margin:0;font-size:28px}.reference-page-heading p{margin:6px 0 0;color:var(--ui-muted);font-size:13px}.reference-heading-actions{display:flex;gap:10px}.reference-layout{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(300px,1fr);gap:18px}.reference-main-column{min-width:0}.storage-hero{display:flex;align-items:center;gap:34px;min-height:205px;padding:26px 32px;color:#fff;background:#7184f8;border-radius:15px;box-shadow:0 16px 30px rgba(113,132,248,.25)}.storage-ring{position:relative;display:grid;place-items:center;width:120px;height:120px;flex:0 0 120px}.storage-ring .el-progress{position:absolute;inset:0}.storage-ring>div:last-child{display:flex;flex-direction:column;align-items:center}.storage-ring strong{font-size:28px}.storage-ring span{font-size:12px;opacity:.84}.storage-copy small,.storage-copy strong,.storage-copy span{display:block}.storage-copy small{font-size:13px;opacity:.82}.storage-copy strong{margin:8px 0;font-size:24px}.storage-copy span{font-size:13px;opacity:.86}.category-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin-top:18px}.category-card{position:relative;display:grid;grid-template-columns:56px 1fr auto;grid-template-rows:auto auto;align-items:center;gap:2px 12px;min-height:142px;padding:20px;text-align:left;background:#fff;border:1px solid var(--ui-border);border-radius:14px;box-shadow:var(--ui-shadow);cursor:pointer}.category-card:hover{border-color:var(--ui-primary);transform:translateY(-2px)}.category-icon{grid-row:1 / span 2;display:grid;place-items:center;width:56px;height:56px;color:#fff;border-radius:50%;font-size:24px;box-shadow:0 8px 12px rgba(0,0,0,.08)}.category-icon.coral{background:#ff7678}.category-icon.blue{background:#4bb7ee}.category-icon.green{background:#39c9aa}.category-icon.purple{background:#db8af1}.category-card strong{font-size:23px;font-weight:500}.category-card small{color:var(--ui-text);font-size:14px}.category-card em{grid-column:2 / span 2;color:var(--ui-muted);font-size:12px;font-style:normal}.reference-side-column{display:grid;grid-template-rows:auto 1fr;gap:18px;min-width:0}.reference-panel{padding:20px;background:#fff;border:1px solid var(--ui-border);border-radius:14px;box-shadow:var(--ui-shadow)}.reference-panel header{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px}.reference-panel h2{margin:0;font-size:19px;font-weight:500}.reference-panel header i{color:var(--ui-primary);font-size:18px}.contact-row{display:grid;grid-template-columns:36px minmax(0,1fr) auto;align-items:center;gap:10px;margin:14px 0}.contact-avatar{display:grid;place-items:center;width:36px;height:36px;color:#fff;border-radius:50%}.admin-avatar{background:#172d47}.server-avatar{background:#dce8ff;color:#5b78dd}.course-avatar{background:#e5f7f2;color:#2bb38e}.contact-row strong,.contact-row small{display:block}.contact-row strong{font-size:13px}.contact-row small{margin-top:3px;color:var(--ui-muted);font-size:11px}.quick-panel button{display:grid;grid-template-columns:28px 1fr auto;align-items:center;gap:10px;width:100%;padding:12px 0;color:var(--ui-text);text-align:left;background:transparent;border:0;border-bottom:1px solid #f0f1f5;cursor:pointer}.quick-panel button:last-child{border-bottom:0}.quick-panel button:hover{color:var(--ui-primary)}.quick-panel button i{color:var(--ui-primary);font-size:18px}.quick-panel button b{color:var(--ui-muted)}@media(max-width:900px){.reference-layout{grid-template-columns:1fr}.reference-side-column{grid-template-columns:repeat(2,minmax(0,1fr));grid-template-rows:none}}@media(max-width:620px){.reference-page-heading{display:block}.reference-heading-actions{margin-top:14px}.reference-layout,.reference-side-column{grid-template-columns:1fr}.storage-hero{gap:20px;padding:22px}.category-grid{grid-template-columns:1fr}}
</style>
